    template <std::size_t Frames, std::size_t Steps>
    constexpr Sprite Make(CreatureId id, const Frame (&frames)[Frames], const Step (&steps)[Steps], int sleepFrame, ImVec4 body, ImVec4 second, ImVec4 third, int facing, bool floats, bool swims, bool stays)
    {
        return { id, frames, static_cast<int>(Frames), steps, static_cast<int>(Steps), sleepFrame, body, second, third, facing, floats, swims, stays };
    }

